<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('roadmap/index.php');verify_csrf();$userId=(int)current_user()['user_id'];$itemId=(int)($_POST['item_id']??0);$status=$_POST['status']??'';$allowed=['not_started','in_progress','completed','skipped'];if(!in_array($status,$allowed,true)){flash('Invalid task status.','error');redirect('roadmap/index.php');}
$st=$pdo->prepare('SELECT ri.item_id,ri.roadmap_id,ri.skill_id,r.user_id FROM roadmap_items ri JOIN roadmaps r ON r.roadmap_id=ri.roadmap_id WHERE ri.item_id=? AND r.user_id=?');$st->execute([$itemId,$userId]);$row=$st->fetch();if(!$row){flash('Roadmap task not found.','error');redirect('roadmap/index.php');}
$st=$pdo->prepare('UPDATE roadmap_items SET status=?,completed_at=? WHERE item_id=?');$st->execute([$status,$status==='completed'?date('Y-m-d H:i:s'):null,$itemId]);if($status==='completed'){award_achievement($pdo,$userId,'ROADMAP_MILESTONE');$log=$pdo->prepare('INSERT INTO progress_logs (user_id,skill_id,roadmap_item_id,note) VALUES (?,?,?,?)');$log->execute([$userId,$row['skill_id'],$itemId,'Completed roadmap task.']);}
$st=$pdo->prepare("SELECT COUNT(*) total,SUM(status='completed') done FROM roadmap_items WHERE roadmap_id=?");$st->execute([$row['roadmap_id']]);$count=$st->fetch();if((int)$count['total']>0&&(int)$count['total']===(int)$count['done']){$st=$pdo->prepare("UPDATE roadmaps SET status='completed' WHERE roadmap_id=?");$st->execute([$row['roadmap_id']]);}else{$st=$pdo->prepare("UPDATE roadmaps SET status='active' WHERE roadmap_id=? AND status='completed'");$st->execute([$row['roadmap_id']]);}
flash('Roadmap task updated.');redirect('roadmap/index.php?id='.(int)$row['roadmap_id']);
